python3 - <<'PY'
import re, os, collections
mods={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn)
            m=p[:-5].replace('/','.')
            mods[m]=p
mods['AlgebraicJacobian']='AlgebraicJacobian.lean'
print('modules (incl. root):', len(mods))
def imports(p):
    out=[]
    for line in open(p):
        s=line.strip()
        if s.startswith('import '):
            out.append(s.split()[-1])
        elif s.startswith('public import '):
            out.append(s.split()[-1])
    return [i for i in out if i.startswith('AlgebraicJacobian')]
g={m:imports(p) for m,p in mods.items()}
def reach(start):
    seen={start}; st=[start]
    while st:
        n=st.pop()
        for k in g.get(n,[]):
            if k not in seen: seen.add(k); st.append(k)
    return seen
head='AlgebraicJacobian.Jacobian'
r=reach(head)
print(f'reachable from {head}: {len(r)}')
# root roll-up
root=reach('AlgebraicJacobian')
print('reachable from root AlgebraicJacobian.lean:', len(root))
unrooted=set(mods)-root
print('unrooted (not reachable from the root):', len(unrooted), sorted(unrooted)[:10])
print('library modules under AlgebraicJacobian/ :', len(mods)-1)
